            var plain = new byte[data.Length - NonceSize - TagSize];
            using var gcm = new AesGcm(_key, TagSize);
            gcm.Decrypt(data.AsSpan(0, NonceSize), data.AsSpan(NonceSize + TagSize), data.AsSpan(NonceSize, TagSize), plain, Ad(associatedData));
